// r44: the CONVERSION SENDER (spec: ./consent.ts conversionPayload). Server-side, consent-aware, OFF unless
// CYRUS_CONVERSIONS=1. An outbox: product code RECORDS an event (deterministic id, so one per account/purchase);
// the worker sweep SENDS it through the host's ad plumbing (host.conversions: Nxeon's Meta CAPI config + Google Ads
// offline-conversion queue) only when the person's stored consent includes marketing, else it is closed as
// `skipped:no_consent`. Retries 3x, then `failed`. A host without `conversions` sends nothing (`skipped:no_transport`).
// Consent + attribution come from the snapshot taken at sign-in (CyrusAttribution, ./attribution-store). SERVER ONLY.
// HOST SEAM: Cyrus tables via cyrusDb, transports via the host.
import { cyrusDb } from "../db";
import { getHost } from "../host";
import { conversionPayload, conversionsEnabled, decodeAttribution, parseConsent, type ConversionId } from "./consent";

type Env = Record<string, string | undefined>;
export const CONVERSION_MAX_ATTEMPTS = 3;
export const conversionEventId = (id: ConversionId, key: string) => `cyrus:${id}:${key}`.slice(0, 120);

export type ConversionRow = { id: string; userId: string; kind: string; valueCents: number | null; currency: string | null; status: string; attempts: number; createdAt: Date };
export type ConversionDeps = {
  insert(r: { id: string; userId: string; kind: ConversionId; valueCents: number | null; currency: string | null }): Promise<boolean>;
  due(limit: number): Promise<ConversionRow[]>;
  mark(id: string, patch: { status: string; attempts?: number; lastError?: string | null; sentAt?: Date | null }): Promise<void>;
  snapshot(userId: string): Promise<{ consent: string | null; attr: string | null } | null>;
  emailSha256(userId: string): Promise<string | null>;
  transport: { meta(ev: Record<string, unknown>): Promise<boolean>; google(ev: Record<string, unknown>, userId: string): Promise<boolean> } | null;
};

/** Record one conversion (no-op while off). Never throws into the product flow. */
export async function recordConversion(i: { id: ConversionId; key: string; userId: string; valueCents?: number | null; currency?: string | null }, deps: Pick<ConversionDeps, "insert"> = prismaConversionDeps(), env: Env = process.env): Promise<boolean> {
  if (!conversionsEnabled(env)) return false;
  try { return await deps.insert({ id: conversionEventId(i.id, i.key), userId: i.userId, kind: i.id, valueCents: i.valueCents ?? null, currency: i.currency ?? null }); }
  catch (e) { console.error("[cyrus-conversions] record failed", (e as Error).message); return false; }
}

export type ConversionSweepResult = { sent: number; skipped: number; retried: number; failed: number };
export async function conversionSweep(deps: ConversionDeps = prismaConversionDeps(), env: Env = process.env, now = new Date()): Promise<ConversionSweepResult> {
  const out: ConversionSweepResult = { sent: 0, skipped: 0, retried: 0, failed: 0 };
  if (!conversionsEnabled(env)) return out;
  for (const r of await deps.due(50)) {
    if (!deps.transport) { await deps.mark(r.id, { status: "skipped:no_transport" }); out.skipped++; continue; }
    const snap = await deps.snapshot(r.userId).catch(() => null);
    const p = conversionPayload({
      id: r.kind as ConversionId, eventId: r.id, atMs: r.createdAt.getTime(), consent: parseConsent(snap?.consent), attribution: decodeAttribution(snap?.attr),
      valueCents: r.valueCents, currency: r.currency ?? undefined, emailSha256: await deps.emailSha256(r.userId).catch(() => null),
    });
    if (!p) { await deps.mark(r.id, { status: "skipped:no_consent" }); out.skipped++; continue; }
    let ok = false, err: string | null = null;
    try { const [m, g] = await Promise.all([deps.transport.meta(p.meta), deps.transport.google(p.google, r.userId)]); ok = m || g; if (!ok) err = "no transport accepted it (not configured?)"; }
    catch (e) { err = (e as Error).message.slice(0, 200); }
    if (ok) { await deps.mark(r.id, { status: "sent", sentAt: now, lastError: null }); out.sent++; continue; }
    const attempts = r.attempts + 1;
    await deps.mark(r.id, { status: attempts >= CONVERSION_MAX_ATTEMPTS ? "failed" : "pending", attempts, lastError: err });
    if (attempts >= CONVERSION_MAX_ATTEMPTS) out.failed++; else out.retried++;
  }
  return out;
}

/** The account's first succeeded build (called from the build-finished hook; inert while off). */
export async function maybeFirstBuildConversion(userId: string, env: Env = process.env): Promise<void> {
  if (!conversionsEnabled(env)) return;
  const n = await cyrusDb.modBuild.count({ where: { userId, status: "succeeded" } }).catch(() => 99);
  if (n === 1) await recordConversion({ id: "first_build", key: userId, userId }, undefined, env);
}

/** Consent + attribution snapshot from cyrus.my cookies at sign-in (CYRUS_ATTRIBUTION or CYRUS_CONVERSIONS). */
export async function saveAttributionSnapshot(userId: string, consentRaw: string | null | undefined, attrRaw: string | null | undefined, env: Env = process.env): Promise<boolean> {
  if (env.CYRUS_ATTRIBUTION !== "1" && !conversionsEnabled(env)) return false;
  const consent = parseConsent(consentRaw);
  const attr = decodeAttribution(attrRaw);
  if (!consent) return false;
  const data = { consent: consentRaw!, attr: attr ? (attrRaw as string) : null };
  await cyrusDb.cyrusAttribution.upsert({ where: { userId }, create: { userId, ...data }, update: data }).catch(() => {});
  return true;
}

export function prismaConversionDeps(): ConversionDeps {
  const t = cyrusDb.cyrusConversion;
  const conv = getHost().conversions ?? null;
  return {
    async insert(r) { try { await t.create({ data: { ...r, status: "pending" } }); return true; } catch (e) { if ((e as { code?: string }).code === "P2002") return false; throw e; } },
    due: (limit) => t.findMany({ where: { status: "pending" }, orderBy: { createdAt: "asc" }, take: limit }),
    async mark(id, patch) { await t.update({ where: { id }, data: patch }); },
    snapshot: (userId) => cyrusDb.cyrusAttribution.findUnique({ where: { userId }, select: { consent: true, attr: true } }),
    async emailSha256(userId) {
      const u = await getHost().users.get(userId);
      if (!u?.email) return null;
      const { createHash } = await import("node:crypto");
      return createHash("sha256").update(u.email.trim().toLowerCase()).digest("hex");
    },
    transport: conv,
  };
}
// r44 NXEON SIDE: the ATTRIBUTION RECEIVER for cyrus.my -> nxeon.cloud sign-ups (CYRUS_ATTRIBUTION, default off).
// cyrus.my keeps a consented attribution cookie (lib/cyrus/analytics/consent.ts); the SSO hand-off carries it as the
// validated `attr` parameter (lib/cyrus/bridge/flow.ts). Here, on the way to /register, a partner code in it becomes
// the SAME `nxeon_ref` cookie /partner/<code> sets, plus one ReferralClick (referer "cyrus.my"), so lib/actions.ts
// register() validates and attaches the Creator Partner exactly as for a direct click; the r38 partner hook
// (lib/nxeon-platform/entitlements.ts cyrusPartnerCommission) then sees that attribution. Nothing else is stored.
// An existing nxeon_ref cookie is replaced only by a DIFFERENT explicit code (same rule as mergeAttribution).
import type { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { attributionEnabled, decodeAttribution } from "@/lib/cyrus/analytics/consent";

export const NXEON_REF_COOKIE = "nxeon_ref";
const TTL_S = 30 * 86_400;

/** The partner code to apply, or null. Pure (tests). */
export function partnerCodeFrom(attr: string | null | undefined, existing: string | null | undefined): string | null {
  const a = decodeAttribution(attr);
  const code = a?.ref?.trim().toUpperCase().slice(0, 32);
  if (!code || !/^[A-Z0-9_-]{2,32}$/.test(code)) return null;
  return existing && existing.toUpperCase() === code ? null : code;
}

export async function receiveCyrusAttribution(req: Request, attr: string | undefined, res: NextResponse, env: Record<string, string | undefined> = process.env): Promise<NextResponse> {
  if (!attributionEnabled(env) || !attr) return res;
  const existing = /(?:^|;\s*)nxeon_ref=([^;]*)/.exec(req.headers.get("cookie") ?? "")?.[1] ?? null;
  const code = partnerCodeFrom(attr, existing);
  if (!code) return res;
  res.cookies.set(NXEON_REF_COOKIE, code, { path: "/", maxAge: TTL_S, sameSite: "lax" });
  await db.referralClick.create({ data: { code, ipHash: null, referer: "cyrus.my (sso hand-off)" } }).catch(() => {});
  return res;
}
// r44 NXEON SIDE: the transports behind host.conversions (lib/cyrus/analytics/conversions.ts). They reuse Nxeon's own
// ad config (lib/tracking.ts loadTrackingConfig: pixel id, CAPI token, test_event_code) and Google Ads offline queue
// (the AdsConversion table the existing googleAdsConversionSweep uploads). Only ever called by the Cyrus conversion
// sweep, which is inert unless CYRUS_CONVERSIONS=1 and only sends with marketing consent.
import { db } from "@/lib/db";
import { loadTrackingConfig } from "@/lib/tracking";

export async function sendMetaEvent(event: Record<string, unknown>): Promise<boolean> {
  const cfg = await loadTrackingConfig();
  if (!cfg.metaPixelId || !cfg.metaCapiToken) return false;
  const url = `https://graph.facebook.com/v21.0/${encodeURIComponent(cfg.metaPixelId)}/events?access_token=${encodeURIComponent(cfg.metaCapiToken)}`;
  const res = await fetch(url, {
    method: "POST", headers: { "Content-Type": "application/json" }, signal: AbortSignal.timeout(5000),
    body: JSON.stringify({ data: [event], ...(cfg.metaTestEventCode ? { test_event_code: cfg.metaTestEventCode } : {}) }),
  });
  return res.ok;
}

/** Queue for the existing Google Ads offline upload (needs a gclid from the consented attribution). */
export async function queueGoogleConversion(event: Record<string, unknown>, userId: string): Promise<boolean> {
  const gclid = typeof event.gclid === "string" ? event.gclid : null;
  if (!gclid) return false;
  const value = typeof event.conversion_value === "number" ? Math.round(event.conversion_value * 100) : null;
  try {
    await db.adsConversion.create({ data: { dedupeKey: String(event.order_id), kind: `cyrus_${String(event.conversion_action)}`.slice(0, 40), userId, gclid, valueCents: value, currency: typeof event.currency_code === "string" ? event.currency_code : "USD", status: "PENDING" } });
    return true;
  } catch (e) { return (e as { code?: string }).code === "P2002"; }
}

