// owner needs to tell apart:
//   - "step"     : the user REACHED this step (drives the classic reach/drop-off funnel)
//   - "error"    : something FAILED on this step — a validation error, an API/
//                  provision failure, an exception. `errorCode`/`errorMessage`
//                  say WHAT tripped them up (bug vs abandonment).
//   - "complete" : the deploy SUCCEEDED (bottom of the funnel).
//   - "select"   : the customer PICKED something in the wizard — a game family,
//                  a plan/tier, a billing term, a region (2026-09-27, for
//                  "what's popular" — see lib/deploy-funnel.ts's
//                  `deploySelections` and lib/plan-popularity.ts, which lines
//                  this up against REAL completed orders). On a "select" row,
//                  `step` holds the SELECTION KIND ("game" | "plan" | "term" |
//                  "region") rather than a wizard step label, and `detail`
//                  carries what was picked as a small JSON string, e.g.
//                  `{"value":"minecraft"}` or
//                  `{"value":"<planId>","ramMB":4096,"term":12}`.
// All ids are nullable so an anonymous / opted-out session still records shape.
// `stepIndex` is the step's position within that session's wizard so events sort
// into wizard order even though optional steps shift the numbering; unused
// (0) on a "select" row, which has no fixed position.
model DeployFunnelEvent {
  id           String   @id @default(cuid())
  userId       String? // signed-in account, when resolvable server-side
  visitorId    String? // stable cookie id, when consent allows
  sessionId    String? // per-tab session id (client), the primary dedupe key
  product      String // vps | game | hosting | email
  step         String // wizard step label reached/errored, OR (type="select") the selection kind
  stepIndex    Int // position of that step within the session's wizard
  type         String   @default("step") // step | error | complete | select
  errorCode    String? // machine code for an error event (e.g. PROVISION_FAILED)
  errorMessage String? // human error text, truncated
  /// (type="select" only) JSON string of what was picked, e.g. `{"value":"minecraft"}`.
  /// Added 2026-09-27 — see prisma/manual-migration-deploy-funnel-select.sql.
  /// NOT yet part of the generated Prisma client shared via this worktree's
  /// symlinked node_modules (regenerating it here would touch /opt/nxeon's live
  /// client before production's own DB has this column) — read/written with raw
  /// SQL ($queryRaw/$executeRaw) in lib/deploy-funnel.ts until a real `db push`
  /// at deploy regenerates the client, at which point the raw-SQL path keeps
  /// working unchanged.
  detail       String?  @db.Text
  createdAt    DateTime @default(now())

  @@index([product, createdAt])
  @@index([product, type])
  /// per-customer reads (admin Activity timeline / wizard progress, signup-fixes 2026-10-06)
  @@index([userId, createdAt])
}

