import { NextResponse } from "next/server";
import { randomUUID } from "node:crypto";
import { db } from "@/lib/db";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { currentUser, impersonating } from "@/lib/auth";
import { parseUserAgent } from "@/lib/ua-parse";
import { classifyHit } from "@/lib/bots/classify";
import { activeIpFlag } from "@/lib/bots/ip-flags";

export const runtime = "nodejs";

/**
 * Page-view capture endpoint. Called fire-and-forget by <VisitTracker/> mounted
 * in the marketing layout and the portal Shell. It records a single `Visit` row
 * and MUST NOT throw or block the caller — analytics is strictly best-effort.
 *
 * The client IP is the PROXY-ATTESTED address (`trustedClientIp`); we never
 * trust a body-supplied IP, nor the first hop of `X-Forwarded-For` — nginx
 * appends to that header, so its first entry is caller-chosen. That mattered
 * twice here: it was the rate-limit key (so one header defeated the 60/min cap
 * on durable row insertion), and it is PERSISTED to `Visit.ip`, which is what
 * the admin visitors/analytics pages attribute traffic and abuse to. A forged
 * value poisoned both.
 *
 * Bots are CLASSIFIED, not dropped (2026-10-01, lib/bots/classify.ts): the row
 * is stored with `isBot`/`botKind`/`botReason` so every analytics read can
 * exclude it by default (and the admin can still see it with "include bots"),
 * and the worker re-classifier (worker/bot-classify.ts) can upgrade a verdict
 * later from behaviour. Before this, a coarse UA regex silently dropped
 * self-declared bots but let headless scrapers (Lightpanda, ~3k rows/day from
 * residential proxies) and stale-UA fleets straight into the human numbers.
 * The visit "kind" (marketing vs portal) comes from a `?k=` query param the
 * mounter sets.
 *
 * Two shapes of POST arrive here:
 *  - a PAGEVIEW (has `path`): inserts the Visit row, attaches session/pvid/utm and
 *    a stable, consent-gated `visitorId` (see below).
 *  - a CLOSE beacon (`{ close, pvid, dur }`, often via navigator.sendBeacon on
 *    pagehide): stamps the dwell time onto the earlier row with that pvid. This is
 *    what makes "avg time on site" and bounce rate possible.
 *
 * Stable visitor id (recurring vs new): we keep a first-party `nx_vid` cookie and
 * persist it on each Visit, so a returning person is recognisable across sessions
 * without any third party. It is CONSENT-GATED to the site's own opt-out model
 * (lib/consent.ts): only minted/persisted unless the visitor explicitly chose
 * "necessary" (nxeon_cookie_consent=necessary), in which case visitorId stays null
 * and that person is only ever counted by the coarse IP path.
 */

const VID_COOKIE = "nx_vid";
const VID_MAX_AGE = 60 * 60 * 24 * 365; // 1 year
const CONSENT_COOKIE = "nxeon_cookie_consent";

/** Read one cookie value out of the raw Cookie header. */
function readCookie(req: Request, name: string): string | null {
  const raw = req.headers.get("cookie");
  if (!raw) return null;
  for (const part of raw.split("; ")) {
    if (part.startsWith(`${name}=`)) return part.slice(name.length + 1);
  }
  return null;
}

/** Clamp a client-supplied opaque id to something sane before it hits the DB. */
function cleanId(v: unknown): string | null {
  if (typeof v !== "string") return null;
  const s = v.trim();
  if (!s || s.length > 64 || !/^[A-Za-z0-9._-]+$/.test(s)) return null;
  return s;
}

function cleanUtm(v: unknown): string | null {
  if (typeof v !== "string") return null;
  const s = v.trim().slice(0, 120);
  return s || null;
}

export async function POST(req: Request) {
  try {
    // Unauthenticated endpoint that writes a durable row per hit — throttle
    // per-IP to cap unbounded row insertion. Over the limit: silent no-op.
    const ip = trustedClientIp(req);
    const rl = checkRateLimit(`track:${ip}`, { max: 120, windowMs: 60_000 });
    if (!rl.ok) {
      return new NextResponse(null, { status: 204 });
    }

    const url = new URL(req.url);
    const kindParam = url.searchParams.get("k");
    const kind = kindParam === "portal" ? "portal" : "marketing";

    const body = (await req.json().catch(() => ({}))) as {
      path?: unknown;
      referrer?: unknown;
      sessionId?: unknown;
      pvid?: unknown;
      isEntry?: unknown;
      utmSource?: unknown;
      utmMedium?: unknown;
      utmCampaign?: unknown;
      gclid?: unknown;
      close?: unknown;
      dur?: unknown;
      ix?: unknown;
      wd?: unknown;
    };

    // --- CLOSE beacon: attach dwell time to the earlier pageview row ---
    if (body.close === true) {
      const pvid = cleanId(body.pvid);
      const durRaw = typeof body.dur === "number" ? body.dur : Number(body.dur);
      if (pvid && Number.isFinite(durRaw)) {
        // Cap at 30 min so a backgrounded tab can't record an absurd dwell.
        const durationMs = Math.min(Math.max(Math.round(durRaw), 0), 30 * 60_000);
        // `ix` = the visitor produced at least one real input event (pointer,
        // scroll, key, touch) on this pageview — a bot-detection signal.
        const interacted = typeof body.ix === "boolean" ? body.ix : undefined;
        await db.visit.updateMany({
          where: { pvid },
          data: { durationMs, ...(interacted !== undefined ? { interacted } : {}) },
        });
      }
      return NextResponse.json({ ok: true });
    }

    const ua = (req.headers.get("user-agent") ?? "").slice(0, 400);
    // An empty UA is never a browser running our beacon — not worth a row.
    if (!ua) {
      return NextResponse.json({ ok: true });
    }
    const { deviceType, os, browser } = parseUserAgent(ua);

    const path =
      typeof body.path === "string" && body.path ? body.path.slice(0, 300) : "/";
    let referrer =
      typeof body.referrer === "string" && body.referrer
        ? body.referrer.slice(0, 400)
        : null;
    // Drop same-origin referrers — they're just internal navigation noise.
    if (referrer) {
      try {
        if (new URL(referrer).host === url.host) referrer = null;
      } catch {
        /* keep opaque referrer strings as-is */
      }
    }

    // --- Stable, consent-gated visitor id ---
    // Opt-out model mirrors lib/consent.ts marketingAllowed(): allowed unless the
    // visitor EXPLICITLY chose "necessary". No cookie is minted for an opted-out
    // person, so they carry no durable id.
    const consent = readCookie(req, CONSENT_COOKIE);
    const idAllowed = consent !== "necessary";
    let visitorId: string | null = null;
    let setVidCookie: string | null = null;
    if (idAllowed) {
      const existing = readCookie(req, VID_COOKIE);
      visitorId = existing && /^[A-Za-z0-9-]{8,64}$/.test(existing) ? existing : randomUUID();
      if (!existing) setVidCookie = visitorId;
    }

    // --- Attribute the signed-in account (THE fix) ---
    // This is a POST from the browser, so the auth cookie rides along and
    // `currentUser()` resolves the same account the portal sees. Attaching the
    // userId is what lets the client profile show that person's OWN page history
    // and their location (portal visits especially). Anonymous marketing traffic
    // resolves to null and is unaffected. Wrapped so an auth hiccup never blocks
    // best-effort capture.
    //
    // EXCEPT while an admin is impersonating: `currentUser()` resolves to the
    // TARGET customer (that's the whole point of impersonation), but `ip`
    // above is the ADMIN's own real, physical address -- the browser making
    // this request never moves. Attaching the target's id would write THIS
    // request under the customer's own identity with the admin's IP/location,
    // which is exactly what corrupted admin/users/[id]'s "Location"/"Sign-in
    // IPs" panel: a fresh entry from the admin's own city, ordered above and
    // indistinguishable from the customer's real, older sign-ins (found live
    // 2026-09-25). This isn't a session or a sign-in at all, so there's no
    // correct non-null attribution to fall back to -- the admin's access is
    // already recorded, correctly attributed, by the `admin.impersonate_start`
    // AuditLog entry (lib/actions-account.ts's `impersonateUser`); this
    // endpoint's job is the customer's own real browsing history, so it must
    // simply skip attribution for the duration of the impersonation grant.
    let userId: string | null = null;
    try {
      const imp = await impersonating();
      userId = imp ? null : ((await currentUser())?.id ?? null);
    } catch {
      /* auth resolution is best-effort; a failure just leaves the visit anon */
    }

    // --- Google Ads click id (gclid) ---
    // Auto-tagging appends `?gclid=…` with NO utm_source, so without this the click
    // lands unattributed and buckets as "(none)". When we have a gclid but the
