}
// Cyrus one-account bridge: which hostnames are "the Cyrus app" and where each side lives. PURE (Edge-safe: the
// middleware imports it), HOST SEAM: no Nxeon imports.
//
//   CYRUS_DOMAIN_MODE=1        the switch. Off (default) = nothing in this folder changes any request.
//   CYRUS_HOSTS                comma list of Cyrus hostnames (default "cyrus.my,www.cyrus.my")
//   CYRUS_ORIGIN               the Cyrus app origin (default https://<first CYRUS_HOSTS entry>)
//   APP_URL                    the Nxeon origin (the identity provider + wallet), as everywhere else
export type BridgeConfig = { enabled: boolean; cyrusHosts: string[]; cyrusOrigin: string; nxeonOrigin: string };

const trimSlash = (s: string) => s.replace(/\/+$/, "");

export function bridgeConfig(env: Record<string, string | undefined> = process.env): BridgeConfig {
  const hosts = (env.CYRUS_HOSTS ?? "cyrus.my,www.cyrus.my").split(",").map((h) => h.trim().toLowerCase()).filter(Boolean);
  return {
    enabled: env.CYRUS_DOMAIN_MODE === "1" && hosts.length > 0,
    cyrusHosts: hosts,
    cyrusOrigin: trimSlash(env.CYRUS_ORIGIN || `https://${hosts[0] ?? "cyrus.my"}`),
    nxeonOrigin: trimSlash(env.APP_URL || "https://nxeon.cloud"),
  };
}

/** True only with the mode on AND an exact (port-less, lower-cased) hostname match. */
export function isCyrusHost(host: string | null | undefined, cfg: BridgeConfig = bridgeConfig()): boolean {
  if (!cfg.enabled || !host) return false;
  return cfg.cyrusHosts.includes(host.toLowerCase().split(":")[0]);
}

/** The request header middleware sets on Cyrus-host requests (and strips from every incoming request). */
export const CYRUS_HOST_HEADER = "x-cyrus-host";

/** Session cookie on the Cyrus host. `__Host-` in production: Secure, path=/, no Domain, so it can never be
 *  scoped to a parent domain or set by a sibling host. */
export const cyrusSessionCookie = (env: Record<string, string | undefined> = process.env) =>
  env.NODE_ENV === "production" ? "__Host-cyrus_session" : "cyrus_session";
/** The short-lived sign-in state cookie (state + nonce + next) on whichever host started a handshake. */
export const ssoStateCookie = (side: "cyrus" | "nxeon", env: Record<string, string | undefined> = process.env) =>
  `${env.NODE_ENV === "production" ? "__Host-" : ""}${side}_sso_state`;

/** The fixed callback URLs. Exact-match only: no prefixes, no query, so redirect_uri can never point elsewhere. */
export const callbackUrls = (cfg: BridgeConfig = bridgeConfig()) => ({
  cyrus: `${cfg.cyrusOrigin}/auth/nxeon/callback`,
  nxeon: `${cfg.nxeonOrigin}/sso/cyrus/return`,
});

