          referrer: document.referrer || null,
          sessionId,
          pvid,
          isEntry,
          utmSource: utm.source ?? null,
          utmMedium: utm.medium ?? null,
          utmCampaign: utm.campaign ?? null,
          gclid: utm.gclid ?? null,
          wd,
        }),
        keepalive: true,
      }).catch(() => {});
    } catch {
      /* fire-and-forget; never disrupt the page */
    }
    // pathname is the dependency; helpers are stable closures.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pathname, kind]);

  // Close the last open pageview when the tab is actually going away.
  useEffect(() => {
    if (typeof window === "undefined") return;
    const onHide = () => closeOpen();
    const onVis = () => {
      if (document.visibilityState === "hidden") closeOpen();
    };
    window.addEventListener("pagehide", onHide);
    document.addEventListener("visibilitychange", onVis);
    return () => {
      window.removeEventListener("pagehide", onHide);
      document.removeEventListener("visibilitychange", onVis);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [kind]);

  /** Send the dwell time for the currently-open pageview, once. */
  function closeOpen() {
    const open = openRef.current;
    if (!open) return;
    openRef.current = null;
    const dur = Date.now() - open.start;
    if (dur < 250) return; // ignore instant bounces / strict-mode churn
    const body = JSON.stringify({ close: true, pvid: open.pvid, dur, ix: interactedRef.current });
    try {
      // sendBeacon survives unload; fall back to keepalive fetch.
      if (navigator.sendBeacon) {
        navigator.sendBeacon(`/api/track?k=${kind}`, new Blob([body], { type: "application/json" }));
      } else {
        fetch(`/api/track?k=${kind}`, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body,
          keepalive: true,
        }).catch(() => {});
      }
    } catch {
      /* best-effort */
    }
  }

  // Honeypot: invisible to people (off-screen, aria-hidden, untabbable) and to
  // well-behaved crawlers (/api is Disallowed in app/robots.ts, and the link is
  // nofollow). Only scrapers that harvest every <a href> fetch it, and
  // app/api/track/hp/route.ts flags the fetching IP.
  return (
    <a
      href="/api/track/hp"
      rel="nofollow"
      tabIndex={-1}
      aria-hidden="true"
      style={{ position: "absolute", left: "-10000px", top: "auto", width: 1, height: 1, overflow: "hidden" }}
    >
      &#8203;
    </a>
  );
}

/** Read the gclid out of Google's `_gcl_aw` cookie (`GCL.<ts>.<gclid>`), if present.
 *  Used as a fallback when the current URL carries no `?gclid=` — e.g. the visitor
 *  clicked the ad, gtag stored the cookie, then navigated deeper before we tracked. */
function readGclAw(): string | undefined {
  try {
    const m = document.cookie.match(/(?:^|;\s*)_gcl_aw=([^;]+)/);
    if (!m) return undefined;
    const parts = decodeURIComponent(m[1]).split(".");
    const id = parts[parts.length - 1];
    return id && id.length > 3 ? id : undefined;
  } catch {
    return undefined;
  }
}

/** Small random id; prefers crypto.randomUUID, falls back for old browsers. */
function genId(): string {
  try {
    if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
  } catch {
    /* ignore */
  }
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}
