const DAY = 86_400_000;

function StatsTable({ rows, label }: { rows: GroupStats[]; label: string }) {
  if (!rows.length) return <Empty>No builds in the last 30 days.</Empty>;
  return (
    <TableWrap>
      <table className="w-full text-sm">
        <thead><tr className={thCls}><th>{label}</th><th className="text-right">Builds</th><th className="text-right">Success</th><th className="text-right">Failed</th><th className="text-right">Refused</th><th className="text-right">Avg</th><th className="text-right">p95</th><th className="text-right">AI cost</th></tr></thead>
        <tbody>
          {rows.map((r) => (
            <tr key={r.key} className={tdRow}>
              <td className="whitespace-nowrap">{r.key}</td>
              <td className="text-right tabular-nums">{n(r.counts.total)}{r.counts.running ? <span className="ml-1 text-xs text-slate-500">({r.counts.running} running)</span> : null}</td>
              <td className="text-right tabular-nums">{pct(rate(r.counts, "succeeded"))}</td>
              <td className="text-right tabular-nums">{pct(rate(r.counts, "failed"))}</td>
              <td className="text-right tabular-nums">{pct(rate(r.counts, "refused"))}</td>
              <td className="text-right tabular-nums">{secs(r.avgMs)}</td>
              <td className="text-right tabular-nums">{secs(r.p95Ms)}</td>
              <td className="text-right tabular-nums">{usd(r.costUsd, 3)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </TableWrap>
  );
}

function MarginTable({ rows, total }: { rows: ModelMargin[]; total: ModelMargin }) {
  return (
    <TableWrap>
      <table className="w-full text-sm">
        <thead><tr className={thCls}><th>Model</th><th className="text-right">Settled builds</th><th className="text-right">AI cost</th><th className="text-right">Tokens charged</th><th className="text-right">Tokens / $ cost</th><th className="text-right">Value of tokens</th><th className="text-right">Margin</th></tr></thead>
        <tbody>
          {[...rows, total].map((r) => (
            <tr key={r.model} className={`${tdRow} ${r.model === "all" ? "font-semibold" : ""}`}>
              <td className="capitalize">{r.model === "all" ? "All models" : r.model}</td>
              <td className="text-right tabular-nums">{n(r.builds)}</td>
              <td className="text-right tabular-nums">{usd(r.costUsd, 3)}</td>
              <td className="text-right tabular-nums">{n(r.tokensCharged)}</td>
              <td className="text-right tabular-nums">{r.tokensPerUsd === null ? "–" : n(r.tokensPerUsd)}</td>
              <td className="text-right tabular-nums">{usd(r.valueUsd)}</td>
              <td className={`text-right tabular-nums ${r.marginUsd < 0 ? "text-red-400" : ""}`}>{usd(r.marginUsd)} <span className="text-xs text-slate-500">{pct(r.marginPct)}</span></td>
            </tr>
          ))}
        </tbody>
      </table>
    </TableWrap>
  );
}

/** Overview / health: real counts only, honest empty states. */
export default async function CyrusAdminOverview({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  // A role without the overview (support, billing) lands on its first tab instead of /admin.
  const me = await realUser();
  if (me && !canSeeCyrusTab(me.role, "overview")) {
    const l = landingCyrusTab(me.role);
    if (l) redirect(l.href);
  }
  await requireCyrusAdmin("overview");
  const sp = await searchParams;
  const now = new Date();
  const since = new Date(now.getTime() - 30 * DAY);
  const cfg = await loadTokenConfig();
  const [rows, running, held, settled, recentFailed, openReports, health] = await Promise.all([
    cyrusDb.modBuild.findMany({ where: { createdAt: { gt: since } }, select: LITE_SELECT, orderBy: { createdAt: "desc" }, take: 5000 }),
    cyrusDb.modBuild.findMany({ where: { status: { notIn: ["succeeded", "failed"] } }, select: { id: true, status: true, createdAt: true }, orderBy: { createdAt: "asc" }, take: 200 }),
    cyrusDb.cyrusTokenReservation.findMany({ where: { status: "held" }, select: { buildId: true, createdAt: true, amount: true }, take: 500 }),
    cyrusDb.cyrusTokenReservation.findMany({ where: { settledAt: { gt: since } }, select: { model: true, charged: true, costUsd: true, status: true }, take: 10000 }),
    cyrusDb.modBuild.findMany({ where: { status: "failed", createdAt: { gt: new Date(now.getTime() - DAY) } }, select: { id: true, errorCode: true, createdAt: true }, take: 500 }),
    cyrusDb.cyrusModReport.count({ where: { resolvedAt: null } }),
    svcHealth(),
  ]);
  const [purchases, flightRows, failed7, evalRaw] = await Promise.all([
    cyrusDb.cyrusTokenLedger.findMany({ where: { kind: "purchase", createdAt: { gt: since } }, select: { kind: true, source: true, meta: true }, take: 20000 }),
    cyrusDb.modBuild.findMany({ where: { createdAt: { gt: new Date(now.getTime() - 7 * DAY) }, status: "succeeded" }, select: { status: true, cyrus: true }, take: 5000 }),
    cyrusDb.modBuild.findMany({ where: { createdAt: { gt: new Date(now.getTime() - 7 * DAY) }, status: "failed" }, select: { id: true, status: true, errorCode: true, createdAt: true }, take: 5000 }),
    readFile(join(process.cwd(), "services/modbuilder/eval/baseline.json"), "utf8").then((t) => JSON.parse(t) as unknown).catch(() => null),
  ]);
  const revenue = revenueFromLedger(purchases);
  const flights = flightSummary(flightRows);
  const errors = topErrors(failed7);
  const evalStatus = readEvalBaseline(evalRaw);
  const holds = await holdsFor(rows.map((r) => r.id));
  const lite = rows.map((r) => toLite(r, holds.get(r.id)?.model));
  const counts = countOutcomes(lite);
  const finishedMs = lite.filter((b) => buildOutcome(b) !== "running" && (b.durationMs ?? 0) > 0).map((b) => b.durationMs!);
  const svc = readHealth(health);
  const heldBuilds = held.length ? await cyrusDb.modBuild.findMany({ where: { id: { in: held.map((h) => h.buildId) } }, select: { id: true, status: true } }) : [];
  const terminal = new Set(heldBuilds.filter((b) => b.status === "succeeded" || b.status === "failed").map((b) => b.id));
  const orphanHolds = held.filter((h) => terminal.has(h.buildId));
  const attention = attentionItems({ now, running, recentFailed, orphanHolds, serviceOk: health === null ? false : svc.reachable, openReports });
  const topupRate = 1 / cfg.topup.tokensPerUsd;
  const planRate = Math.min(...PLAN_TIERS.map((t) => cfg.plan.cents[t] / 100 / Math.max(1, cfg.plan.tokens[t])));
  const mTop = marginByModel(settled, topupRate);
  const mPlan = marginByModel(settled, planRate);
  const cost30 = lite.reduce((a, b) => a + b.costUsd, 0);

  return (
    <div>
      <Flash sp={sp} />
      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Builds, 30 days" value={n(counts.total)} delta={`${n(counts.succeeded)} ok · ${n(counts.failed)} failed · ${n(counts.refused)} refused`} deltaGood={counts.failed <= counts.succeeded} />
        <StatCard label="Success rate (finished)" value={pct(rate(counts, "succeeded"))} delta={counts.finished ? `${pct(rate(counts, "refused"))} refused by safety` : "nothing finished yet"} />
        <StatCard label="Build time avg / p95" value={`${secs(mean(finishedMs))} / ${secs(percentile(finishedMs, 95))}`} delta={`${finishedMs.length} timed builds`} />
        <StatCard label="Queue now" value={svc.reachable ? `${n(svc.running)} running · ${n(svc.queued)} queued` : `${running.length} in flight`} delta={svc.reachable ? `service capacity ${n(svc.concurrency)} at once` : "service not answering"} deltaGood={svc.reachable} />
      </div>

      <Section title="Needs attention" sub="Computed from live rows: stuck builds, lost contact with the builder, holds left after a build finished, the service, open reports.">
        {attention.length === 0 ? <Empty>Nothing needs attention right now.</Empty> : (
          <ul className="space-y-2">
            {attention.map((a) => (
              <li key={a.code} className="flex flex-wrap items-start gap-2 text-sm">
                <Badge tone={a.level === "red" ? "red" : "amber"}>{a.level === "red" ? "urgent" : "check"}</Badge>
                <span className="min-w-0 flex-1">{a.text}</span>
                {a.href ? <Link href={a.href} className="btn-secondary text-xs">Open</Link> : null}
              </li>
            ))}
          </ul>
        )}
      </Section>

      <div className="grid min-w-0 gap-0 xl:grid-cols-3 xl:gap-6">
        <Section title="Spend vs revenue, 30 days" sub="Revenue = what customers paid for Cyrus tokens (top-ups + plan invoices, from the token ledger; Stripe test-mode money counted apart). Spend = AI cost of every build in the window.">
          <Kv rows={[
            ["Revenue", `${usd(revenue.totalCents / 100)} (${n(revenue.purchases)} payments)`],
            ["Top-ups / plans", `${usd(revenue.topupCents / 100)} / ${usd(revenue.planCents / 100)}`],
            ["AI spend", usd(cost30, 2)],
            ["Revenue minus AI spend", <span key="m" className={revenue.totalCents / 100 - cost30 < 0 ? "text-red-400" : ""}>{usd(revenue.totalCents / 100 - cost30)}</span>],
            ...(revenue.testCents ? [["Test-mode payments", usd(revenue.testCents / 100)] as [string, React.ReactNode]] : []),
            ...(revenue.unknown ? [["Purchases without an amount", n(revenue.unknown)] as [string, React.ReactNode]] : []),
          ]} />
        </Section>
        <Section title="Test Flight, 7 days" sub="Boot test of each succeeded build (Paper on node-2). Not run is never counted as passed.">
          {flights.total === 0 ? <Empty>No succeeded builds in 7 days.</Empty> : (
            <Kv rows={[
              ["Passed", `${n(flights.passed)} of ${n(flights.total)}`],
              ["Failed", n(flights.failed)],
              ["Incomplete / not run", `${n(flights.incomplete)} / ${n(flights.notRun)}`],
              ["Queued or running", n(flights.pending)],
              ["Never queued (gate off)", n(flights.none)],
            ]} />
