// Page gate for /admin/cyrus/**. Server only.
//   1. role: requireArea(<the tab's area>) (lib/cyrus/admin/perms.ts) - redirects like every admin page;
//   2. private preview: the REAL signed-in account must be on the "modbuilder" allowlist, else a plain
//      404 (the section is indistinguishable from a route that does not exist), like /admin/mod-builder.
// The admin layout already refuses impersonation.
import { notFound } from "next/navigation";
import { getHost, type HostUser } from "../host";
import { CYRUS_ADMIN_TABS, type CyrusAdminTab } from "./perms";

export async function requireCyrusAdmin(tab: CyrusAdminTab): Promise<HostUser> {
  const area = CYRUS_ADMIN_TABS.find((t) => t.id === tab)!.area;
  const host = getHost();
  const user = await host.auth.requireArea(area);
  if (!(await host.access.isPreviewUser(await host.auth.realUser(), "modbuilder"))) notFound();
  return user;
}

export async function cyrusAdminMetadata(title: string) {
  const host = getHost();
  const ok = await host.access.isPreviewUser(await host.auth.realUser().catch(() => null), "modbuilder");
  return { title: ok ? `Cyrus · ${title}` : "Page not found", robots: { index: false, follow: false } };
}

/**
 * Route-handler guard for /api/admin/cyrus/** (r40). Same rule as the pages and the server actions, but returns null
 * instead of redirecting, so the route answers a plain 404: the real account, not impersonating, on the "modbuilder"
 * preview list, with the action's role area. Fails closed on any error.
 */
export async function cyrusAdminApiUser(action: import("./perms").CyrusAdminAction): Promise<HostUser | null> {
  try {
    const { CYRUS_ADMIN_ACTIONS } = await import("./perms");
    const host = getHost();
    const [real, cur] = await Promise.all([host.auth.realUser(), host.auth.currentUser()]);
    if (!real || !cur || real.id !== cur.id) return null;
    if (!host.access.canAccess(real.role, CYRUS_ADMIN_ACTIONS[action])) return null;
    if (!(await host.access.isPreviewUser(real, "modbuilder"))) return null;
    return real;
  } catch {
    return null;
  }
}
// Cyrus admin "Economy" tab (2026-10-13): the PROJECTED token economy per plan, computed from the live token config.
// PURE and client-safe (the margin preview in the browser runs the same functions the server page does).
// Unit-tested in test/cyrus-admin-economy.test.ts. A projection: nothing here charges, grants or blocks anyone, and
// every warning is a soft one (decision D-62: warn, do not block).
//
// How the numbers connect (lib/cyrus/tokens/economy.ts): a build is charged  costUsd x tokensPerUsd x mult[model]  tokens.
// So `tokens` of a plan buy  tokens / (tokensPerUsd x mult)  dollars of AI cost; the cheapest multiplier is the worst case
// for us (the same tokens buy the most AI work there).
import { PLAN_TIERS, parseTokenConfig, type PlanTier, type TokenConfig } from "../tokens/config-pure";
import { TIER_LABEL, TIER_MODELS } from "../tokens/economy";
import type { CyrusModelId } from "../models";

export const ECON_SETTINGS = {
  stripePct: "cyrus_econ_stripe_pct",
  stripeFixedCents: "cyrus_econ_stripe_fixed_cents",
  marginWarnPct: "cyrus_econ_margin_warn_pct",
} as const;
export const ECON_DEFAULTS = { stripePct: 2.9, stripeFixedCents: 30, marginWarnPct: 40 } as const;
export type EconFees = { stripePct: number; stripeFixedCents: number; marginWarnPct: number };

/** Typical cost of one build per model when too few are measured (BL-token-savings-plan.md). Yakko costs like Saka; its x1.25 multiplier is in the token price. */
export const FALLBACK_BUILD_COST_USD: Record<CyrusModelId, number> = { katara: 0.09, saka: 0.55, yakko: 0.55 };
export const MIN_MEASURED_BUILDS = 5;

export function parseEconFees(stored: Partial<Record<string, string>>): EconFees {
  const n = (k: string, d: number, max: number) => {
    const raw = stored[k];
    const v = Number(raw);
    return raw === undefined || raw.trim() === "" || !Number.isFinite(v) || v < 0 ? d : Math.min(max, v);
  };
  return {
    stripePct: n(ECON_SETTINGS.stripePct, ECON_DEFAULTS.stripePct, 20),
    stripeFixedCents: n(ECON_SETTINGS.stripeFixedCents, ECON_DEFAULTS.stripeFixedCents, 500),
    marginWarnPct: n(ECON_SETTINGS.marginWarnPct, ECON_DEFAULTS.marginWarnPct, 100),
  };
}

// ---------------------------------------------------------------------------
// Measured cost per model
// ---------------------------------------------------------------------------

export type MeasuredBuild = { model: string; costUsd: number; succeeded: boolean };
export type ModelCost = { model: CyrusModelId; medianUsd: number; n: number; source: "measured" | "fallback" };

const median = (xs: number[]) => { const s = [...xs].sort((a, b) => a - b); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };

/** Median cost of a SUCCEEDED, priced build per model; under MIN_MEASURED_BUILDS samples the documented fallback is used and labelled. */
export function medianCostByModel(builds: MeasuredBuild[]): Record<CyrusModelId, ModelCost> {
  const out = {} as Record<CyrusModelId, ModelCost>;
  for (const m of ["katara", "saka", "yakko"] as CyrusModelId[]) {
    const xs = builds.filter((b) => b.model === m && b.succeeded && Number.isFinite(b.costUsd) && b.costUsd > 0).map((b) => b.costUsd);
    out[m] = xs.length >= MIN_MEASURED_BUILDS
      ? { model: m, medianUsd: median(xs), n: xs.length, source: "measured" }
      : { model: m, medianUsd: FALLBACK_BUILD_COST_USD[m], n: xs.length, source: "fallback" };
  }
  return out;
}

// ---------------------------------------------------------------------------
// Per plan
// ---------------------------------------------------------------------------

export type EconWarning = { level: "red" | "amber"; code: string; text: string };
export type PlanBuilds = { model: CyrusModelId; medianUsd: number; source: ModelCost["source"]; tokensPerBuild: number; buildsPerPeriod: number };
export type PlanEconomics = {
  tier: PlanTier;
  label: string;
  priceUsd: number;
  tokens: number;
  /** tokens / tokensPerUsd: the AI spend the tokens stand for at multiplier 1 */
  budgetUsd: number;
  /** worst case: all tokens spent on the model with the cheapest multiplier */
  worstCostUsd: number;
  stripeFeeUsd: number;
  marginBeforeFeesUsd: number;
  marginBeforeFeesPct: number;
  marginAfterFeesUsd: number;
  marginAfterFeesPct: number;
  builds: PlanBuilds[];
  warnings: EconWarning[];
};

const r2 = (x: number) => Math.round(x * 100) / 100;

export function planEconomics(i: { cfg: TokenConfig; fees: EconFees; costs: Record<CyrusModelId, ModelCost> }): PlanEconomics[] {
  const { cfg, fees, costs } = i;
  return PLAN_TIERS.map((tier) => {
    const priceUsd = cfg.plan.cents[tier] / 100;
    const tokens = cfg.plan.tokens[tier];
    const models = TIER_MODELS[tier];
    const minMult = Math.min(...models.map((m) => cfg.mult[m]));
    const budgetUsd = tokens / cfg.tokensPerUsd;
    const worstCostUsd = tokens / (cfg.tokensPerUsd * minMult);
    const stripeFeeUsd = (priceUsd * fees.stripePct) / 100 + fees.stripeFixedCents / 100;
    const before = priceUsd - worstCostUsd;
    const after = before - stripeFeeUsd;
    const builds: PlanBuilds[] = [...models].reverse().map((m) => {
      const tokensPerBuild = Math.max(cfg.minSpend, costs[m].medianUsd * cfg.tokensPerUsd * cfg.mult[m]);
      return { model: m, medianUsd: costs[m].medianUsd, source: costs[m].source, tokensPerBuild: Math.round(tokensPerBuild), buildsPerPeriod: tokensPerBuild > 0 ? Math.floor(tokens / tokensPerBuild) : 0 };
    });
